source env.sh && source .venv/bin/activate && sed -i '' "s/calling from Freya Bank on a recorded call\. Am I speaking/calling from Freya Bank, and we record this call. Am I speaking/g" out/gen_brief-a.py && python3 out/gen_brief-a.py tools/openapi.json && python3 - <<'EOF'
import json
wf=json.load(open('out/brief-a.workflow.json'))
nodes={n['name']:n for n in wf['nodes']}
def code(n):
    return nodes[n]['pre_actions'][0]['code'] if 'pre_actions' in nodes[n] else nodes[n].get('code')
import datetime, re
for now, prod in [("2026-10-14T11:00", {"product_id":"p1","type":"credit_card","card_last4":"4821","past_due":420.5,"minimum_payment":60,"days_late":5}),
                  ("2026-10-23T15:30", {"product_id":"p1","type":"car_loan","past_due":900,"instalment_amount":300,"days_late":20})]:
    vars={"now":now,"title":"Mr","last_name":"Reyes","products":[prod]}
    for n in ("setup","prepare"):
        c=code(n); exec(c, {"vars":vars,"json":json,"re":re,"datetime":datetime})
    print(now, {k:vars.get(k) for k in ("today_text","attempt1_date","early_deadline","late_deadline","deadline_text","say_next","callback_text","setup_state")})
EOF
